const lead = $json;

const errors = [];

if (!lead.lead_id) {
  errors.push('Missing lead_id');
}

if (!lead.company_name) {
  errors.push('Missing company_name');
}

if (lead.validation_status !== 'VALID') {
  errors.push(
    `Invalid WF-01 validation_status: ${lead.validation_status || 'MISSING'}`
  );
}

if (!lead.company_domain_normalized && !lead.company_domain) {
  errors.push('Missing company domain');
}

return {
  json: {
    lead,
    input_validation_status:
      errors.length === 0 ? 'VALID' : 'NEEDS_REVIEW',
    input_validation_errors: errors
  }
};

