const tavilyItems = $input.all();
const queryItems = $('Split Research Queries').all();

const output = [];

for (let i = 0; i < tavilyItems.length; i++) {
  const tavily = tavilyItems[i].json;
  const queryContext = queryItems[i]?.json || {};

  const results = Array.isArray(tavily.results)
    ? tavily.results
    : [];

  for (let j = 0; j < results.length; j++) {
    const result = results[j];

    output.push({
      json: {
        research_id: queryContext.research_id,
        company_name: queryContext.company_name,
        company_domain: queryContext.company_domain,

        query_index: queryContext.query_index,
        query_type: queryContext.query_type,

        search_query:
          tavily.query ||
          queryContext.search_query ||
          '',

        search_rank: j + 1,

        source_title:
          String(result.title || '').trim(),

        source_url:
          String(result.url || '').trim(),

        search_snippet:
          String(result.content || '').trim(),

        relevance_score:
          typeof result.score === 'number'
            ? result.score
            : null,

        discovery_provider: 'tavily',

        source_type: 'SEARCH_RESULT',

        source_tier: 3,

        retrieval_status: 'DISCOVERED'
      }
    });
  }
}

return output;

const items = $input.all();

return items.map(item => {
  const data = item.json;

  let normalizedUrl = '';

  try {
    const url = new URL(data.source_url);

    url.protocol = 'https:';
    url.hostname = url.hostname.toLowerCase();

    if (url.hostname.startsWith('www.')) {
      url.hostname = url.hostname.slice(4);
    }

    url.hash = '';

    const trackingParams = [
      'utm_source',
      'utm_medium',
      'utm_campaign',
      'utm_term',
      'utm_content',
      'gclid',
      'fbclid',
      'mc_cid',
      'mc_eid'
    ];

    trackingParams.forEach(param => {
      url.searchParams.delete(param);
    });

    normalizedUrl = url.toString();

    if (normalizedUrl.endsWith('/')) {
      normalizedUrl = normalizedUrl.slice(0, -1);
    }

  } catch (error) {
    normalizedUrl = data.source_url || '';
  }

  return {
    json: {
      ...data,
      source_url_normalized: normalizedUrl
    }
  };
});

const items = $input.all();

function getHostname(value) {
  if (!value) return '';

  const text = String(value).trim();

  const match = text.match(/^https?:\/\/([^/?#]+)/);

  if (!match) return '';

  return match[1]
    .toLowerCase()
    .replace(/^www\./, '')
    .split(':')[0];
}

function normalizeDomain(value) {
  if (!value) return '';

  return String(value)
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .split('/')[0]
    .split(':')[0];
}

const externalBusinessDomains = [
  'linkedin.com',
  'crunchbase.com',
  'zoominfo.com',
  'leadiq.com',
  'apollo.io',
  'glassdoor.com'
];

const industryPublicationDomains = [
  'reuters.com',
  'techcrunch.com',
  'forbes.com',
  'businesswire.com',
  'prnewswire.com'
];

const socialDomains = [
  'facebook.com',
  'instagram.com',
  'x.com',
  'twitter.com'
];

function matchesDomain(host, domain) {
  return host === domain || host.endsWith(`.${domain}`);
}

return items.map(item => {
  const data = item.json;

  const sourceUrl =
    data.source_url_normalized ||
    data.source_url ||
    '';

  const sourceHost = getHostname(sourceUrl);

  const companyDomain = normalizeDomain(
    data.company_domain
  );

  let sourceClass = 'OTHER';
  let sourceTier = 3;

  if (
    sourceHost &&
    companyDomain &&
    matchesDomain(sourceHost, companyDomain)
  ) {
    sourceClass = 'COMPANY_OFFICIAL';
    sourceTier = 1;
  } else if (
    externalBusinessDomains.some(domain =>
      matchesDomain(sourceHost, domain)
    )
  ) {
    sourceClass = 'EXTERNAL_BUSINESS';
    sourceTier = 2;
  } else if (
    industryPublicationDomains.some(domain =>
      matchesDomain(sourceHost, domain)
    )
  ) {
    sourceClass = 'INDUSTRY_PUBLICATION';
    sourceTier = 2;
  } else if (
    socialDomains.some(domain =>
      matchesDomain(sourceHost, domain)
    )
  ) {
    sourceClass = 'SOCIAL_PROFILE';
    sourceTier = 2;
  }

  return {
    json: {
      ...data,
      source_host: sourceHost,
      company_domain_normalized: companyDomain,
      source_class: sourceClass,
      source_tier: sourceTier,
      source_priority:
        sourceClass === 'COMPANY_OFFICIAL'
          ? 1
          : sourceTier === 2
            ? 2
            : 3
    }
  };
});

const input = $json;

const statusCode = Number(input.statusCode ?? 0);

const body = String(
  input.data ??
  input.body ??
  ''
);

const normalized = body
  .replace(/\s+/g, ' ')
  .trim()
  .toLowerCase();

const bodyLength = body.length;

const blockedSignals = [
  'captcha',
  'verify you are human',
  'access denied',
  'cloudflare',
  'checking your browser',
  'just a moment',
  'bot detection',
  'unusual traffic',
  'enable javascript'
];

const isBlocked = blockedSignals.some(
  signal => normalized.includes(signal)
);

let retrieval_status;
let retrieval_reason;

if (statusCode >= 200 && statusCode < 300) {

  if (bodyLength < 300) {
    retrieval_status = 'empty';
    retrieval_reason = 'Response body is too short';

  } else if (isBlocked) {
    retrieval_status = 'blocked';
    retrieval_reason = 'Detected bot/challenge/block page';

  } else {
    retrieval_status = 'success';
    retrieval_reason = 'Usable HTTP response received';
  }

} else if (statusCode === 403) {

  retrieval_status = 'blocked';
  retrieval_reason = 'HTTP 403 Forbidden';

} else if (statusCode === 404) {

  retrieval_status = 'not_found';
  retrieval_reason = 'HTTP 404 Not Found';

} else if (statusCode === 429) {

  retrieval_status = 'rate_limited';
  retrieval_reason = 'HTTP 429 Too Many Requests';

} else if (statusCode >= 500) {

  retrieval_status = 'server_error';
  retrieval_reason = `HTTP ${statusCode}`;

} else if (statusCode >= 400) {

  retrieval_status = 'client_error';
  retrieval_reason = `HTTP ${statusCode}`;

} else {

  retrieval_status = 'unknown';
  retrieval_reason = 'HTTP status code unavailable';
}

return {
  json: {
    ...input,
    retrieval_status,
    retrieval_reason,
    retrieval_status_code: statusCode,
    retrieval_body_length: bodyLength,
    research_attempted: true,
    research_retrieved: retrieval_status === 'success'
  }
};
